solutionCode:
pub fn entrega(pilha: &mut Vec<i32>) -> Option<i32> {
    pilha.pop()
}

testsCode:
use desafio::entrega;

#[test]
fn testa_a_entrega_do_ultimo() {
    let mut pilha = vec![1, 2, 3];
    assert_eq!(entrega(&mut pilha), Some(3));
}

#[test]
fn testa_a_pilha_que_acabou() {
    let mut pilha = vec![5];
    assert_eq!(entrega(&mut pilha), Some(5));
    assert_eq!(entrega(&mut pilha), None);
}
